import random
import re

MAX_RADIUS = 10**6
REFERENCE_LIMIT = 32
SMALL_RADII = (1, 2, 4, 26, 3, 5, 6, 7, 8)
MONOTONE_CASES = ((1, 2), (2, 3), (3, 4), (4, 26), (25, 26))


def _integer_token(text: str) -> str | None:
    tokens = text.split()
    if len(tokens) != 1:
        return None
    token = tokens[0]
    if re.fullmatch(r"[+-]?[0-9]+", token) is None:
        return None
    return token


def _bounded_integer(token: str, max_magnitude: int) -> int | None:
    digits = token.lstrip("+-").lstrip("0") or "0"
    limit = str(max_magnitude)
    if len(digits) > len(limit):
        return None
    value = int(digits)
    if value > max_magnitude:
        return None
    return -value if token.startswith("-") else value


def _radius(inp: str) -> int | None:
    token = _integer_token(inp)
    if token is None:
        return None
    radius = _bounded_integer(token, MAX_RADIUS)
    if radius is None or radius < 1:
        return None
    return radius


def validate_input(inp: str) -> bool:
    return _radius(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    radii = list(SMALL_RADII[:max(0, n)])
    radii.extend(rng.randint(1, 8) for _ in range(n - len(radii)))
    return [f"{radius}\n" for radius in radii]


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    nearby = MAX_RADIUS - rng.randint(1, 1000)
    return [f"{MAX_RADIUS}\n", f"{nearby}\n"]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    radius = _radius(inp)
    if radius is None:
        return []

    token = _integer_token(out)
    if token is None:
        return [("POST-2", "Expected exactly one base-10 integer.")]

    lower = 4 * radius - 3
    upper = (2 * radius - 1) ** 2
    value = _bounded_integer(token, upper)
    if value is None or value < lower:
        return [("POST-3", f"The answer must be in [{lower}, {upper}].")]
    if value % 4 != 1:
        return [("POST-3", "The answer must be congruent to 1 modulo 4.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = list(MONOTONE_CASES[:max(0, n)])
    for _ in range(n - len(pairs)):
        smaller = rng.randint(1, REFERENCE_LIMIT - 1)
        larger = rng.randint(smaller + 1, REFERENCE_LIMIT)
        pairs.append((smaller, larger))
    return [
        ("POST-4", "le", f"{smaller}\n", f"{larger}\n")
        for smaller, larger in pairs
    ]


def reference_small(inp: str) -> str | None:
    radius = _radius(inp)
    if radius is None or radius > REFERENCE_LIMIT:
        return None

    # Coordinates outside this range have a corner outside the circle.
    centers = range(-radius, radius + 1)
    squared_diameter = (2 * radius) ** 2
    total = 0
    for i in centers:
        for j in centers:
            # Double each corner coordinate to test the distance exactly.
            if all(
                (2 * i + di) ** 2 + (2 * j + dj) ** 2 <= squared_diameter
                for di in (-1, 1)
                for dj in (-1, 1)
            ):
                total += 1
    return f"{total}\n"
